// We use the Verus verifier to prove correctness of this function.
// The function finds the minimum element in a non-empty Vec<i32>.

verus! {

    /// Returns the smallest value in a non-empty vector of i32.
    ///
    /// Requires:
    ///     nums.len() > 0
    ///
    /// Ensures:
    /// 1) The result is less than or equal to every element in the vector.
    /// 2) The result is equal to at least one element in the vector.
    fn smallest_num(nums: &Vec<i32>) -> i32
        requires
            nums.len() > 0,
        ensures
            // result <= nums[i] for all i
            forall |i: usize| i < nums.len() ==> result <= nums[i],
        ensures
            // There exists some i with result == nums[i]
            exists |i: usize| i < nums.len() && result == nums[i],
    {
        // Initialize `min` to the first element.
        let mut min: i32 = nums[0];
        // We'll scan from index 1 up to nums.len().
        let mut i: usize = 1;

        // Invariant: at the start of each iteration,
        //   0 <= i <= nums.len(),
        //   for all j < i, min <= nums[j],
        //   there exists some j < i with min == nums[j].
        while i < nums.len()
            invariant
                i <= nums.len(),
            invariant
                forall |j: usize| j < i ==> min <= nums[j],
            invariant
                exists |j: usize| j < i && min == nums[j],
            decreases
                nums.len() - i
        {
            let current = nums[i];
            if current < min {
                // Found a new smaller element
                min = current;
            }
            i += 1;
        }

        // At loop exit, i == nums.len(), so the invariants imply:
        //   for all j < nums.len(), min <= nums[j]
        //   exists j < nums.len() with min == nums[j]
        // which are exactly our postconditions.
        min
    }

} // end of verus!